import '../core/theme.dart';
class SaiLogo extends StatelessWidget {const SaiLogo({super.key,this.size=46});final double size;@override Widget build(BuildContext context)=>ClipRRect(borderRadius:BorderRadius.circular(size*.22),child:Image.asset('assets/images/sai_logo_reference.png',width:size,height:size,fit:BoxFit.cover,errorBuilder:(_,__,___)=>Icon(Icons.school,color:SaiColors.red,size:size)));}
class SaiHeader extends StatelessWidget {const SaiHeader({super.key,required this.title,this.subtitle,this.actions});final String title;final String? subtitle;final List<Widget>? actions;@override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.fromLTRB(20,18,20,12),child:Row(children:[const SaiLogo(size:48),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontSize:19,fontWeight:FontWeight.w800)),if(subtitle!=null)Text(subtitle!,style:const TextStyle(color:SaiColors.muted,fontSize:12))])),...?actions]));}
