class SaiTile extends StatelessWidget {const SaiTile({super.key,required this.title,required this.icon,this.subtitle,this.onTap,this.trailing});final String title;final String? subtitle;final IconData icon;final VoidCallback? onTap;final Widget? trailing;@override Widget build(BuildContext context)=>Card(margin:const EdgeInsets.only(bottom:10),child:InkWell(borderRadius:BorderRadius.circular(18),onTap:onTap,child:Padding(padding:const EdgeInsets.all(15),child:Row(children:[Container(width:44,height:44,decoration:BoxDecoration(color:SaiColors.red.withValues(alpha:.07),borderRadius:BorderRadius.circular(13)),child:Icon(icon,color:SaiColors.red)),const SizedBox(width:14),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontWeight:FontWeight.w700,fontSize:15)),if(subtitle!=null)Text(subtitle!,style:const TextStyle(color:SaiColors.muted,fontSize:12),maxLines:2,overflow:TextOverflow.ellipsis)])),trailing??const Icon(Icons.chevron_left,color:SaiColors.muted)]))));}
class SaiMetric extends StatelessWidget {const SaiMetric({super.key,required this.value,required this.label,required this.icon});final String value,label;final IconData icon;@override Widget build(BuildContext context)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(icon,color:SaiColors.red),const SizedBox(height:12),Text(value,style:const TextStyle(fontSize:25,fontWeight:FontWeight.w900)),Text(label,style:const TextStyle(color:SaiColors.muted,fontSize:12))])));}
class SaiPage extends StatelessWidget {const SaiPage({super.key,required this.title,required this.children,this.subtitle,this.actions});final String title;final String? subtitle;final List<Widget> children;final List<Widget>? actions;@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontWeight:FontWeight.w800,fontSize:17)),if(subtitle!=null)Text(subtitle!,style:const TextStyle(fontSize:11,color:SaiColors.muted))]),actions:actions),body:SafeArea(child:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:920),child:ListView(padding:const EdgeInsets.all(18),children:children)))));}
class AsyncList extends StatelessWidget {const AsyncList({super.key,required this.future,required this.builder,this.empty='لا توجد بيانات متاحة'});final Future<List<Map<String,dynamic>>> future;final Widget Function(List<Map<String,dynamic>>) builder;final String empty;@override Widget build(BuildContext context)=>FutureBuilder<List<Map<String,dynamic>>>(future:future,builder:(context,s){if(!s.hasData){if(s.hasError)return Padding(padding:const EdgeInsets.all(20),child:SelectableText('تعذّر تحميل البيانات. تحقق من صلاحيات الحساب أو اتصال قاعدة البيانات.\n${s.error}',style:const TextStyle(color:SaiColors.red)));return const Center(child:Padding(padding:EdgeInsets.all(30),child:CircularProgressIndicator()));}if(s.data!.isEmpty)return Padding(padding:const EdgeInsets.all(28),child:Text(empty,textAlign:TextAlign.center));return builder(s.data!);});}
